"explanation": "成層圏のオゾン層は特定フロン（CFC）やハロン等によって破壊される。ウィーン条約とモントリオール議定書（1987年採択）により、これら物質の生産・消費が段階的に規制・全廃されてきた。\n\nB：オゾン層破壊の原因はフロン等であり二酸化硫黄ではない。規制枠組みも京都議定書（温暖化）ではなくモントリオール議定書で誤り。\nC：オゾン層破壊は成層圏オゾンの「減少」であり、地表付近のオゾン増加（光化学スモッグ）とは逆の現象で誤り。\nD：フロンは成層圏で塩素原子を放出しオゾンを破壊するため、規制対象とされており誤り。\n\n【混同注意】「オゾン層保護＝モントリオール議定書」「温暖化＝京都議定書・パリ協定」を区別する。\n【混同注意】成層圏オゾン（保護対象）と地表付近のオゾン（光化学オキシダント、削減対象）の違いに注意。"

