"explanation": "環境リスクは、物質固有の有害性（ハザード）の程度と、人や生態系がその物質にさらされる量（暴露量）の双方の組合せによって評価される。有害性が高くても暴露がなければリスクは小さい。\n\nA：有害性のみで決まるとするのは誤り。暴露量も不可欠な要素。\nC：暴露量のみで決まるとするのは誤り。有害性も考慮する。\nD：リスク評価は被害発生前に行う未然防止のための手法であり、被害発生後にのみ評価するという記述は誤り。\n\n【頻出】「リスク＝有害性（ハザード）×暴露量」という基本式が要点。\n【混同注意】無毒性量（NOAEL）や許容一日摂取量（ADI／TDI）、不確実係数などの用語と併せて整理する。"

