"explanation": "総量規制は、工場・事業場が集合し、施設ごとの排出基準（濃度規制やK値規制）のみでは環境基準の確保が困難な指定地域において、特定工場ごとに総量規制基準を定めて排出総量を抑える規制である。硫黄酸化物・窒素酸化物が対象。\n\nA：総量規制は政令で指定された地域に適用されるもので、全国一律・地域指定なしとするのは誤り。\nC：個々の煙突高さで定めるのはK値規制であり、地域の総量を抑える総量規制とは異なるため誤り。\nD：排出濃度を問わず燃料の種類のみを規制するという記述は誤り。\n\n【頻出】総量規制は「指定地域」「工場集合地域」「環境基準確保が困難」が要点。\n【混同注意】K値規制（個別発生源ごと）と総量規制（地域内の工場ごとに総量割当）の役割の違いを区別する。"

