"answer": 0,

"explanation": "理論空気量とは、燃料を完全燃焼させるのに理論上必要な最小限の空気量である。燃料の組成（炭素・水素・硫黄等）から理論酸素量を求め、空気中の酸素割合（体積比約21%）で割って算出する。\n\nB：過剰空気を供給するための量ではなく、必要最小限の空気量を指すため誤り。\nC：排ガス中の残存空気量ではないため誤り。\nD：発熱量を空気量で割った指標ではないため誤り。\n\n【頻出】理論空気量＝完全燃焼に必要な最小空気量、理論酸素量÷0.21で算出という点が頻出。\n【混同注意】実際の燃焼では完全燃焼確保のため理論空気量より多い空気を供給する。その比が空気比であり、両者を区別する。"

