"answer": 1,

"explanation": "空気比（空気過剰率）は、実際の供給空気量を理論空気量で割った値である。完全燃焼を確保するため実際には理論空気量より多く供給するため、通常は1より大きい値（m＞1）となる。\n\nA：分母と分子が逆であり、また常に1未満とするのも誤り。空気比は実際空気量÷理論空気量で1以上となるのが普通。\nC：発熱量を空気量で割った値ではないため誤り。\nD：排ガス量を燃料量で割った値や燃焼温度とは異なるため誤り。\n\n【頻出】空気比 m＝実際空気量／理論空気量、通常 m＞1 が要点。\n【混同注意】空気比が大きすぎると排ガス量増加で熱損失・サーマルNOx増、小さすぎると不完全燃焼でCO増。適正な空気比管理が重要。"

