"explanation": "排煙脱硫は、排ガス中の硫黄酸化物（主に二酸化硫黄）を石灰石・消石灰などのアルカリ性の吸収剤で吸収・反応させて除去する技術である。湿式法（石灰石膏法等）と乾式法がある。\n\nA：アンモニアで窒素酸化物を還元するのは排煙脱硝（SCR）であり、脱硫ではないため誤り。\nB：ばいじんを電気的に捕集するのは電気集じんであり、脱硫ではないため誤り。\nD：一酸化炭素の酸化は燃焼管理や酸化触媒の役割で、脱硫とは異なるため誤り。\n\n【混同注意】脱硫（SOx除去）・脱硝（NOx除去）・集じん（ばいじん除去）の対象物質を取り違えないこと。\n【頻出】排煙脱硫の対象はSO2であり、アルカリ吸収剤で中和・除去する点が要点。"

