"explanation": "排ガス処理は、ボイラ出口の高温側でアンモニア接触還元法による脱硝（約350℃前後の適温が必要）を行い、その後に空気予熱器で熱回収して排ガスを冷却し、集じん（電気集じん等）、続いて湿式脱硫を行って煙突から排出する配置が一般的である。\n\nA：硫黄酸化物・ばいじん・窒素酸化物を除去するため各設備が用いられるため、無処理排出とするのは誤り。\nB：脱硝・集じん・脱硫はそれぞれ専用の装置で行うため、同一装置でまとめて行うとするのは誤り。\nC：脱硝は高温側で先に行うのが一般的で、集じん・脱硫を先にして最後に脱硝するという順序は適温の点で誤り。\n\n【頻出】脱硝（高温側）→集じん→脱硫（低温側）という処理順序は頻出。\n【混同注意】脱硝に適温（約350℃）が必要なため高温側に置く理由を、SCRの反応温度と関連づけて押さえる。"

