"explanation": "電気集じん装置は、圧力損失が小さく、大容量の排ガスを処理しながら微細な粒子も高効率で捕集できるのが特徴で、火力発電所等で広く用いられる。一方、設置面積が大きく、粉じんの電気抵抗率に性能が左右される。\n\nA：電気集じんは圧力損失が小さく微細粒子も捕集できるため、圧損大・微細粒子不可とするのは誤り。\nC：微細粒子も高効率で捕集できるため、粗大粒子のみとするのは誤り。\nD：大容量の処理に適し火力発電所等で広く使われるため、小容量限定・発電所で使われないとするのは誤り。\n\n【頻出】電気集じんの長所（低圧損・大容量・微細粒子高効率）は頻出。\n【混同注意】長所が多い一方で、設置面積が大きく電気抵抗率の影響を受ける短所も押さえる。"

